INSERT INTO inventario.envases (
    envases_id, producto_id, proveedor_id, contenido_inicial_ml,
    contenido_actual_ml, estado, costo_compra, observacion,
    created_at, updated_at
)
SELECT
    md5(b.codigo || g.n::text)::uuid,
    b.producto_id,
    b.proveedor_id,
    b.contenido_ml,
    b.contenido_ml,
    'cerrada',
    b.costo_compra,
    b.observacion,
    b.comprado_en,
    b.comprado_en
FROM (
    VALUES
    ('nacional', '83000000-0000-4000-8000-000000000001'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 244, 355::numeric, 1.05::numeric, TIMESTAMPTZ '2026-10-02 18:00:00-06', 'Compra de cerveza nacional.'),
    ('importada', '83000000-0000-4000-8000-000000000002'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 72, 355::numeric, 1.846::numeric, TIMESTAMPTZ '2026-10-02 18:10:00-06', 'Compra de cerveza importada.'),
    ('cola', '83000000-0000-4000-8000-000000000003'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 132, 355::numeric, 0.781::numeric, TIMESTAMPTZ '2026-10-02 18:20:00-06', 'Compra de gaseosa cola.'),
    ('agua', '83000000-0000-4000-8000-000000000004'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 72, 600::numeric, 0.480::numeric, TIMESTAMPTZ '2026-10-02 18:30:00-06', 'Compra de agua mineral.'),
    ('tequila', '83000000-0000-4000-8000-000000000005'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 18, 750::numeric, 20.025::numeric, TIMESTAMPTZ '2026-10-02 18:40:00-06', 'Compra de tequila.'),
    ('ron', '83000000-0000-4000-8000-000000000006'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 12, 750::numeric, 14.025::numeric, TIMESTAMPTZ '2026-10-02 18:50:00-06', 'Compra de ron.'),
    ('vodka', '83000000-0000-4000-8000-000000000007'::uuid, '82000000-0000-4000-8000-000000000001'::uuid, 8, 750::numeric, 15.975::numeric, TIMESTAMPTZ '2026-10-02 19:00:00-06', 'Compra de vodka.')
) AS b(codigo, producto_id, proveedor_id, unidades, contenido_ml, costo_compra, comprado_en, observacion)
CROSS JOIN LATERAL generate_series(1, b.unidades) AS g(n)
ON CONFLICT DO NOTHING;

