INSERT INTO operaciones.registros_afluencia (
    registros_afluencia_id, usuario_id, tipo_movimiento,
    cantidad, observacion, created_at
)
SELECT
    ('89000000-0000-4000-8000-' || lpad(n::text, 12, '0'))::uuid,
    CASE WHEN EXTRACT(DOW FROM fecha) IN (5) THEN '80000000-0000-4000-8000-000000000002'::uuid
         ELSE '80000000-0000-4000-8000-000000000003'::uuid END,
    tipo,
    cantidad,
    CASE WHEN tipo = 'entrada' THEN 'Ingreso de clientes.' ELSE 'Salida de clientes.' END,
    fecha + hora
FROM (
    VALUES
